$('download-progress').onclick=()=>{try{const data=GameProgress.exportData(),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='asterfall-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('progress-file-message').textContent='Progress downloaded. Keep this file in your Google Drive or another lasting location.';}catch(error){$('progress-file-message').textContent=error.message;}};
$('restore-progress').onclick=()=>$('progress-file').click();$('progress-file').onchange=async event=>{try{const file=event.target.files?.[0];if(!file)return;if(file.size>3000000)throw Error('That file is too large for a progress backup.');GameProgress.restoreData(JSON.parse(await file.text()));$('progress-file-message').textContent='Progress restored.';}catch(error){$('progress-file-message').textContent=error.message;}finally{$('progress-file').value='';}};

