 c.runeLevels.forEach(g=>{g.power=rank;g.vitality=rank;});for(const g of c.progression.gear){g.weapon=gear==='maximum'?12:gear==='chapter'?Math.min(12,chapter*3):0;g.armor=gear==='maximum'?8:gear==='chapter'?Math.min(8,chapter*2):0;g.assault=gear==='basic'?0:Math.min(5,chapter+1);g.support=gear==='basic'?0:Math.min(5,chapter+1);}for(const key of Object.keys(c.progression.materials))c.progression.materials[key]=999;
