 if(dungeon&&c.playtest.openGates){for(const id of dungeon==='rootbound'?['crypt-runes','crypt-hidden-latch','crypt-winch']:dungeon==='frostmine'?['frostmine-lock']:[dungeon+'-puzzle'])if(nodes.some(n=>n.id===id)&&!c.completed.includes(id))c.completed.push(id);}
